begin;
set search_path=public,extensions;
select no_plan();
select is((select default_locale from organization_settings where id=md5('org-1')::uuid),'fr-FR','existing organization backfilled');
select ok(not exists(select 1 from professional_profiles where preferred_locale is not null),'browser choice not materialized in profiles');
select ok(not exists(select 1 from categories c left join category_translations t on t.category_id=c.id and t.locale='fr-FR' where t.label is distinct from c.name),'French category backfill exact');
select ok(not exists(select 1 from verticals v left join vertical_translations t on t.vertical_id=v.id and t.locale='fr-FR' where t.label is distinct from v.name),'French vertical backfill exact');
select ok(not exists(select 1 from hold_reasons h left join hold_reason_translations t on t.hold_reason_id=h.id and t.locale='fr-FR' where t.label is distinct from h.label),'French hold reason backfill exact');
select throws_ok($$update organization_settings set default_locale='de-DE'$$,'23514',null,'unsupported organization locale rejected');
select throws_ok($$update professional_profiles set preferred_locale='en'$$,'23514',null,'unsupported profile locale rejected');
select throws_ok($$insert into category_translations(category_id,locale,label) select id,'fr-FR',name from categories limit 1$$,'23505',null,'unique entity locale');
delete from hold_reason_translations where locale='en-GB' and organization_id=md5('org-1')::uuid;
select throws_ok($$insert into hold_reason_translations(organization_id,hold_reason_id,locale,label) select md5('org-2')::uuid,id,'en-GB','Other' from hold_reasons where organization_id=md5('org-1')::uuid$$,'23503',null,'translation cannot reparent tenant');
select is((select t.label from category_translations t join categories c on c.id=t.category_id where c.code='blocked_access' and locale='en-GB'),'Blocked access or ramp','synthetic English category seeded');
select is((select t.label from vertical_translations t join verticals v on v.id=t.vertical_id where v.code='accessibility' and locale='en-GB'),'Accessibility','synthetic English vertical seeded');
select throws_ok($$update organization_settings set default_locale=null where id=md5('org-1')::uuid$$,'23502',null,'organization default cannot be null');
select lives_ok($$insert into verticals(code,name) values('legacy-long-locale',repeat('L',250))$$,'French synchronization preserves historical unbounded labels');
select throws_ok($$insert into verticals(code,name) values('legacy-empty-locale','')$$,'23514',null,'historical nonempty label constraint preserved');
select set_config('request.jwt.claim.sub',md5('user-1-agent')::uuid::text,true);
set local role authenticated;
select is((select count(*) from organization_settings),0::bigint,'agent cannot read settings');
select is((select organization_locale from get_locale_preferences()),'fr-FR','agent reads only locale projection');
select lives_ok($$select set_preferred_locale('en-GB')$$,'agent updates self');
select is((select preferred_locale from get_locale_preferences()),'en-GB','explicit user preference returned');
select lives_ok($$select set_preferred_locale(null)$$,'reset inheritance');
select throws_ok($$select set_preferred_locale('de-DE')$$,'23514',null,'RPC validates locale');
select throws_ok($$update professional_profiles set preferred_locale='en-GB' where id=md5('user-2-agent')::uuid$$,'42501',null,'no cross-user direct write');
select throws_ok($$select set_organization_locale(md5('org-1')::uuid,'en-GB')$$,'42501','Forbidden','agent cannot configure org');
select throws_ok($$select save_reference_translation('category',(select id from categories limit 1),'en-GB','Forged')$$,'42501','Forbidden','agent cannot edit global catalogue');
reset role;
select set_config('request.jwt.claim.sub',md5('user-1-supervisor')::uuid::text,true);
set local role authenticated;
select throws_ok($$select set_organization_locale(md5('org-1')::uuid,'en-GB')$$,'42501','Forbidden','supervisor is not admin');
reset role;
select set_config('request.jwt.claim.sub',md5('user-1-client_admin')::uuid::text,true);
select set_config('request.headers','{"x-acticiv-command-id":"c011ec70-0000-4000-8000-000000000010"}',true);
select set_config('acticiv.correlation_id','',true);
set local role authenticated;
select lives_ok($$select set_organization_locale(md5('org-1')::uuid,'en-GB')$$,'admin configures own organization');
select throws_ok($$select set_organization_locale(md5('org-2')::uuid,'en-GB')$$,'42501','Forbidden','cross-tenant organization rejected');
select lives_ok($$select save_reference_translation('hold_reason',(select id from hold_reasons limit 1),'en-GB','Awaiting a third party')$$,'own hold reason translated');
select lives_ok($$select save_reference_translation('hold_reason',(select id from hold_reasons limit 1),'fr-FR','Attente externe')$$,'French translation updates historical source');
select is((select label from hold_reasons limit 1),'Attente externe','single French write contract');
select is((select label from hold_reason_translations where locale='fr-FR' limit 1),'Attente externe','French projection synchronized');
select ok(exists(select 1 from audit_events where entity_type='organization_settings' and changes ? 'default_locale' and actor_id=auth.uid() and correlation_id='c011ec70-0000-4000-8000-000000000010'),'organization locale audited with real actor and correlation');
reset role;
select throws_ok($$update category_translations set label='Divergent' where locale='fr-FR'$$,'23514','French label must match source','cannot diverge French translation');
-- An audit failure must roll back the preference and every translation side effect.
create function pg_temp.fail_locale_audit() returns trigger language plpgsql as $$begin raise exception 'Injected audit failure'; end$$;
create trigger fail_locale_audit before insert on audit_events for each row execute function pg_temp.fail_locale_audit();
set local role authenticated;
select throws_ok($$select set_preferred_locale('en-GB')$$,'P0001','Injected audit failure','preference fails atomically with audit');
select is((select preferred_locale from get_locale_preferences()),null,'preference rollback proven');
select throws_ok($$select save_reference_translation('hold_reason',(select id from hold_reasons limit 1),'fr-FR','Rolled back')$$,'P0001','Injected audit failure','translation fails atomically with audit');
select is((select label from hold_reasons limit 1),'Attente externe','historical label rolled back');
reset role;
drop trigger fail_locale_audit on audit_events;
select set_config('request.jwt.claim.sub',md5('user-1-agent')::uuid::text,true);
update organization_memberships set status='inactive' where user_id=md5('user-1-agent')::uuid;
set local role authenticated;
select is((select count(*) from get_locale_preferences()),0::bigint,'inactive membership has no locale projection');
select throws_ok($$select set_preferred_locale('en-GB')$$,'42501','Forbidden','inactive membership cannot mutate preference');
reset role;
update organization_memberships set status='active' where user_id=md5('user-1-agent')::uuid;
update organizations set status='inactive' where id=md5('org-1')::uuid;
set local role authenticated;
select is((select count(*) from get_locale_preferences()),0::bigint,'inactive organization has no locale projection');
select throws_ok($$select set_preferred_locale('en-GB')$$,'42501','Forbidden','inactive organization cannot mutate preference');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select throws_ok($$select * from get_locale_preferences()$$,'42501',null,'anonymous locale projection denied');
select throws_ok($$select set_preferred_locale('en-GB')$$,'42501',null,'anonymous preference denied');
reset role;
select * from finish();
rollback;
